def ARM(c, v): return [plain(unicodedata.normalize('NFKC', x)).strip('.:()') for x in clean(onk_he[c - 1][v - 1]).rstrip(':').split()]
def SEATS(sub): return [(c + 1, v + 1) for c in range(34) for v in range(len(onk_he[c])) if sub in ' '.join(ARM(c + 1, v + 1))]
assert SEATS('גאל דמא') == [(19, 6), (19, 12)] and len(SEATS('קטול')) == 12 and (19, 3) in SEATS('קטול') and (21, 22) in SEATS('קטול') and SEATS('בלא מנדעיה') == [(19, 4)] and SEATS('על מימר') == [(1, 26), (17, 6), (17, 10), (17, 11), (19, 15), (21, 5), (33, 3), (34, 5)] and SEATS('בית דינא') == [(25, 7)] and SEATS('סהדין') == [(17, 6), (19, 15)] and SEATS('סהיד שקר') == [(19, 16), (19, 18)] and len(SEATS('דינא')) == 14 and (19, 17) in SEATS('דינא') and len(SEATS('קרויך')) == 25 and len(SEATS('עממיא')) == 59   # "by the memra of" (al memar) at 19:15's two and three witnesses and 21:5's "by their word"; the false witness "sahid sheqar" at 19:16 and 19:18 alone
assert len(SEATS('אגחא קרב')) == 13 and [s for s in SEATS('אגחא קרב') if s[0] in CHS] == [(20, 1), (20, 2), (20, 3), (20, 5), (20, 6), (20, 7), (20, 10), (21, 10)] and SEATS('סרכ') == [(1, 15), (20, 5), (20, 8), (20, 9), (29, 9), (31, 28)] and SEATS('קטיל') == [(21, 1), (21, 2), (21, 3), (21, 6), (32, 42)] and SEATS('עגלת') == [(21, 3), (21, 4), (21, 6)] and SEATS('נקפ') == [(21, 4), (21, 6)] and SEATS('כהניא בני לוי') == [(21, 5), (31, 9)] and SEATS('טופר') == [(21, 12)] and SEATS('ירח יומין') == [(21, 13)] and SEATS('תתגר') == [(2, 5), (2, 9), (2, 19), (21, 14), (23, 25), (23, 26)] and SEATS('שניאתא') == [(21, 15), (21, 16), (21, 17)] and SEATS('בוכרא') == [(15, 19), (21, 15), (21, 16), (21, 17), (25, 6)] and SEATS('סטי ומרי') == [(21, 18), (21, 20)] and SEATS('ירגמ') == [(21, 21), (22, 21)] and SEATS('צליב') == [(21, 22), (21, 23)] and SEATS('דחב קדם יי') == [(21, 23)] and len(SEATS('מרחק')) == 11 and len(SEATS('עבד דביש')) == 10 and (19, 19) in SEATS('עבד דביש') and (21, 21) in SEATS('עבד דביש')   # "to wage battle" (le-agacha kerava) thirteen seats, eight in the three chapters; "deal with her as merchandise" (titgar) the root of 2:5's "contend not" and 23:25-26's "reap not"; the doer of evil at 19:19 and 21:21 (the purge formula's persons again)
assert ARM(19, 6)[:4] == ['דילמא', 'ירדוף', 'גאל', 'דמא'] and ARM(19, 6)[-7:] == ['ארי', 'לא', 'סני', 'הוא', 'ליה', 'מתמלי', 'ומדקמוהי'] and ARM(19, 10)[:5] == ['ולא', 'ישתפך', 'דם', 'זכי', 'בגו'] and ARM(19, 13) == ['לא', 'תחוס', 'עינך', 'עלוהי', 'ותפלי', 'אשדי', 'דם', 'זכי', 'מישראל', 'וייטב', 'לך'] and ARM(19, 15)[13:22] == ['על', 'מימר', 'תרין', 'סהדין', 'או', 'על', 'מימר', 'תלתא', 'סהדין'] and ARM(19, 16) == ['ארי', 'יקום', 'סהיד', 'שקר', 'בגבר', 'לאסהדא', 'ביה', 'סטיא'] and ARM(19, 17)[5:10] == ['דינא', 'קדם', 'יי', 'קדם', 'כהניא']   # "purge the innocent blood" rendered "REMOVE THE SHEDDERS of innocent blood" — the purge as persons a third time; the false charge (sarah) rendered "deviation" (setya)
assert ARM(20, 1)[:7] == ['ארי', 'תפוק', 'לאגחא', 'קרבא', 'על', 'בעלי', 'דבבך'] and ARM(20, 1)[-7:] == ['יי', 'אלהך', 'מימריה', 'בסעדך', 'דאסקך', 'מארעא', 'דמצרים'] and 'מימריה' in ARM(20, 1) and ARM(20, 4) == ['ארי', 'יי', 'אלהכון', 'דמדבר', 'קדמיכון', 'לאגחא', 'לכון', 'קרב', 'עם', 'בעלי', 'דבביכון', 'למפרק', 'יתכון'] and ARM(20, 5)[:2] == ['וימללון', 'סרכיא'] and ARM(20, 5)[-3:] == ['וגבר', 'אחרן', 'יחנכניה'] and ARM(20, 8)[6:11] == ['מן', 'גברא', 'דדחל', 'ותביר', 'לבא'] and ARM(20, 11)[-3:] == ['מסקי', 'מסין', 'ויפלחנך'] and ARM(20, 19)[-7:] == ['לא', 'כאנשא', 'אילן', 'חקלא', 'למיעל', 'מקדמך', 'בצירא']   # 20:1's "the LORD your God is with you" → "HIS MEMRA IS YOUR HELP"; 20:4's "goes with you" → "leads before you … TO SAVE YOU"; 20:19's question "is the tree of the field a man?" rendered a STATEMENT: "for the tree of the field is not like a man, to come before you in the siege"
assert ARM(21, 1)[:3] == ['ארי', 'ישתכח', 'קטילא'] and ARM(21, 1)[-5:] == ['בחקלא', 'לא', 'אתידע', 'מן', 'קטליה'] and ARM(21, 4)[5:13] == ['עגלתא', 'לנחלא', 'ביר', 'די', 'לא', 'אתפלח', 'ביה', 'ולא'] and ARM(21, 4)[-5:] == ['וינקפון', 'תמן', 'ית', 'עגלתא', 'בנחלא'] and ARM(21, 5)[9:] == ['לשמשותיה', 'ולברכא', 'בשמא', 'דיי', 'ועל', 'מימרהון', 'יהי', 'כל', 'דין', 'וכל', 'מכתש', 'סגירו'] and ARM(21, 7) == ['ויתיבון', 'ויימרון', 'ידנא', 'לא', 'אשדו', 'ית', 'דמא', 'הדין', 'ועיננא', 'לא', 'חזאה'] and ARM(21, 8)[:4] == ['כהניא', 'יימרון', 'כפר', 'לעמך'] and ARM(21, 8)[-3:] == ['להון', 'על', 'דמא']   # "every stroke" → "every plague of confinement" (17:8's word); "our hands have not shed" the plural (the qere); 21:8 ONKELOS ADDS "THE PRIESTS SHALL SAY" — the verse's subjectless "atone" given its speaker (Sotah 9:6)
assert ARM(21, 12) == ['ותעלנה', 'לגו', 'ביתך', 'ותגלח', 'ית', 'רישה', 'ותרבי', 'ית', 'טופרנהא'] and ARM(21, 14)[-10:] == ['וזבנא', 'לא', 'תזבננה', 'בכספא', 'לא', 'תתגר', 'בה', 'חלף', 'די', 'עניתה'] and ARM(21, 17)[2:11] == ['בוכרא', 'בר', 'שניאתא', 'יפרש', 'למתן', 'ליה', 'תרתין', 'חלקין', 'בכל'] and ARM(21, 17)[-5:] == ['ריש', 'תקפיה', 'ליה', 'חזיא', 'בכרותא'] and ARM(21, 18)[3:6] == ['בר', 'סטי', 'ומרי'] and ARM(21, 20)[-4:] == ['זלל', 'בסר', 'וסבי', 'חמר'] and ARM(21, 22) == ['וארי', 'יהי', 'בגבר', 'חובת', 'דין', 'דקטול', 'ויתקטל', 'ותצלוב', 'יתיה', 'על', 'צליבא'] and ARM(21, 23)[10:16] == ['ארי', 'על', 'דחב', 'קדם', 'יי', 'אצטלב']   # "do her nails" → "let her nails GROW" (R. Eliezer's reading, Yevamot 48a); "a glutton and a drunkard" → "a glutton of MEAT and a drinker of WINE" (Sanhedrin 8:2's objects supplied); "a curse of God is one hanged" → "BECAUSE HE SINNED BEFORE THE LORD HE WAS HANGED" — the cause for the curse
